class Solution:
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        ans = []
        for x in nums1:
            idx = nums2.index(x)
            greater = -1
            for y in nums2[idx + 1:]:
                if y > x:
                    greater = y
                    break
            ans.append(greater)
        return ans

