class Solution:
    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:
        pos = {x: i for i, x in enumerate(nums2)}
        ans = []
        for x in nums1:
            greater = -1
            for i in range(pos[x] + 1, len(nums2)):
                if nums2[i] > x:
                    greater = nums2[i]
                    break
            ans.append(greater)
        return ans

